"""Recurring transactions, detection and the cash-flow calendar over HTTP.

"Today" is frozen at 2026-06-30. A synthetic ledger generated by code
(invented payees and amounts) on a checking account the member may edit and
the viewer may view:

* ``STREAMFLIX #<n>``: -15.99 on the 5th, July 2025 to June 2026 (monthly)
* ``Payroll``: +2500.00 every 14 days from 2026-01-02 (biweekly, last 06-19)
* ``City Power``: -70.00..-110.00 on the 20th, January to June (monthly,
  variable)
* ``Corner Grocer``: irregular gaps (not recurring)

and a hidden checking account (no grants) with its own monthly subscription.
"""

from __future__ import annotations

import uuid
from collections.abc import Iterator
from dataclasses import dataclass
from datetime import UTC, date, datetime, timedelta
from decimal import Decimal
from typing import Any

import pytest
from sqlalchemy import select

from app.auth.models import GrantLevel
from app.core.settings import Settings
from app.db.rls import set_context
from app.domain.accounts.models import Account, AccountType
from app.domain.recurring import service as recurring_service
from app.domain.reports.dates import add_months
from app.domain.transactions.models import ScheduledTransaction, ScheduleOrigin
from app.workers.handlers import recurring as recurring_handler
from app.workers.registry import JobContext
from tests.fixtures.factories import AuthedClient, Factories
from tests.fixtures.households import API, Actors, household_audit, household_events, problem_type
from tests.fixtures.ledger import LedgerFactories, make_scheduled_transaction

pytestmark = pytest.mark.integration

REC = f"{API}/recurring"
CAL = f"{API}/cashflow/calendar"
TODAY = date(2026, 6, 30)
D = Decimal


@dataclass(frozen=True)
class World:
    owner: AuthedClient
    member: AuthedClient
    viewer: AuthedClient
    household_id: uuid.UUID
    checking: Account
    hidden: Account
    ledger: LedgerFactories
    factories: Factories


@pytest.fixture
def actors(settings: Settings, factories: Factories) -> Iterator[Actors]:
    with Actors.open(settings, factories) as built:
        yield built


def synthetic_ledger(ledger: LedgerFactories, checking: Account, hidden: Account) -> None:
    for i in range(12):
        ledger.transaction(
            checking,
            amount="-15.99",
            posted_date=add_months(date(2025, 7, 5), i),
            raw_payee=f"STREAMFLIX #{4100 + i}",
        )
    day = date(2026, 1, 2)
    while day <= TODAY:
        ledger.transaction(checking, amount="2500.00", posted_date=day, raw_payee="Payroll")
        day += timedelta(days=14)
    for i, amount in enumerate(["-80.00", "-95.00", "-110.00", "-70.00", "-100.00", "-85.00"]):
        ledger.transaction(
            checking,
            amount=amount,
            posted_date=add_months(date(2026, 1, 20), i),
            raw_payee="City Power",
        )
    day = date(2026, 1, 1)
    for i in range(20):
        ledger.transaction(checking, amount="-42.10", posted_date=day, raw_payee="Corner Grocer")
        day += timedelta(days=2 if i % 2 else 11)
    for i in range(6):
        ledger.transaction(
            hidden,
            amount="-7.00",
            posted_date=add_months(date(2026, 1, 12), i),
            raw_payee="Secret Club",
        )


@pytest.fixture
def world(
    actors: Actors, ledger: LedgerFactories, factories: Factories, monkeypatch: pytest.MonkeyPatch
) -> World:
    monkeypatch.setattr(recurring_service, "today", lambda: TODAY)
    owner = actors.new(role="owner")
    household = owner.record.household
    assert household is not None
    member = actors.new(role="member", household=household)
    viewer = actors.new(role="viewer", household=household)
    hid = household.id
    checking = ledger.account(hid, type=AccountType.CHECKING, name="Checking")
    hidden = ledger.account(hid, type=AccountType.CHECKING, name="Hidden")
    synthetic_ledger(ledger, checking, hidden)
    ledger.grant(hid, member.record.id, checking, GrantLevel.EDIT)
    ledger.grant(hid, viewer.record.id, checking, GrantLevel.VIEW)
    return World(owner, member, viewer, hid, checking, hidden, ledger, factories)


def _ok(response: Any, status: int = 200) -> Any:
    assert response.status_code == status, response.text
    return response.json() if response.content else None


def _schedules(world: World) -> list[ScheduledTransaction]:
    with world.factories.transaction() as db:
        set_context(db, world.household_id)
        return list(
            db.execute(
                select(ScheduledTransaction).order_by(ScheduledTransaction.next_due)
            ).scalars()
        )


def test_candidates_are_a_dry_run_over_visible_accounts(world: World) -> None:
    body = _ok(world.viewer.get(f"{REC}/candidates"))
    assert body["as_of"] == TODAY.isoformat()
    by_name = {c["name"]: c for c in body["items"]}
    assert set(by_name) == {"STREAMFLIX #4111", "Payroll", "City Power"}
    stream = by_name["STREAMFLIX #4111"]
    assert (stream["pattern"], stream["cadence"], stream["interval_count"]) == (
        "monthly",
        "monthly",
        1,
    )
    assert stream["amount_min"] == {"amount": "-15.99", "currency": "USD"}
    assert stream["next_due"] == "2026-07-05"
    assert stream["confidence"] == "1.00"
    assert stream["schedule_id"] is None
    payroll = by_name["Payroll"]
    assert (payroll["pattern"], payroll["cadence"], payroll["interval_count"]) == (
        "biweekly",
        "weekly",
        2,
    )
    assert payroll["next_due"] == "2026-07-03"
    assert D(by_name["City Power"]["confidence"]) < D("1")
    assert _schedules(world) == []
    # The owner also sees the hidden account's pattern.
    owner = _ok(world.owner.get(f"{REC}/candidates"))
    assert "Secret Club" in {c["name"] for c in owner["items"]}
    hidden = world.member.get(f"{REC}/candidates", params={"account": str(world.hidden.id)})
    assert hidden.status_code == 404
    assert problem_type(hidden) == "account-not-found"


def test_detect_writes_editable_accounts_and_is_idempotent(world: World) -> None:
    first = _ok(world.member.post(f"{REC}/detect", json={}))
    assert (first["created"], first["updated"], first["unchanged"]) == (3, 0, 0)
    rows = _schedules(world)
    assert {r.account_id for r in rows} == {world.checking.id}
    assert {r.origin for r in rows} == {ScheduleOrigin.DETECTED}
    assert all(r.active for r in rows)
    power = next(r for r in rows if r.name == "City Power")
    assert (power.amount_min, power.amount_max) == (D("-110.00"), D("-70.00"))
    assert power.next_due == date(2026, 7, 20)
    assert power.last_seen_on == date(2026, 6, 20)
    again = _ok(world.member.post(f"{REC}/detect", json={}))
    assert (again["created"], again["updated"], again["unchanged"]) == (0, 0, 3)
    assert len(_schedules(world)) == 3
    assert {i["schedule_id"] for i in again["items"]} == {str(r.id) for r in rows}
    assert household_audit(world.factories, world.household_id, "schedule.detect")
    assert household_events(world.factories, world.household_id, "schedule.created")
    refused = world.member.post(f"{REC}/detect", json={"account_ids": [str(world.hidden.id)]})
    assert refused.status_code == 404
    viewer = world.viewer.post(f"{REC}/detect", json={})
    assert viewer.status_code == 403


def test_manual_wins_and_switched_off_stays_off(world: World) -> None:
    world.ledger.run(
        make_scheduled_transaction,
        world.checking,
        name="Payroll",
        cadence="weekly",
        next_due=date(2026, 7, 3),
        amount_min="2500.00",
        amount_max="2500.00",
    )
    # The factory has no interval: make it biweekly through the API.
    manual = next(r for r in _schedules(world) if r.origin is ScheduleOrigin.MANUAL)
    _ok(world.owner.patch(f"{REC}/{manual.id}", json={"interval_count": 2}))
    result = _ok(world.owner.post(f"{REC}/detect", json={}))
    assert result["skipped_manual"] == 1
    assert result["created"] == 3  # streamflix, power, and the hidden account's club
    stream = next(r for r in _schedules(world) if r.name.startswith("STREAMFLIX"))
    _ok(world.member.patch(f"{REC}/{stream.id}", json={"active": False, "name": "Video"}))
    world.ledger.transaction(
        world.checking, amount="-16.49", posted_date=TODAY, raw_payee="STREAMFLIX #9"
    )
    later = _ok(world.owner.post(f"{REC}/detect", json={}))
    assert later["updated"] >= 1
    after = next(r for r in _schedules(world) if r.id == stream.id)
    assert (after.active, after.name) == (False, "Video")
    assert after.last_seen_on == TODAY
    assert after.amount_max == D("-15.99")
    assert after.amount_min == D("-16.49")


def test_manual_crud_and_permissions(world: World) -> None:
    body = {
        "account_id": str(world.checking.id),
        "name": "Rent",
        "cadence": "monthly",
        "next_due": "2026-07-01",
        "amount_min": {"amount": "-1200.00", "currency": "USD"},
        "amount_max": {"amount": "-1200.00", "currency": "USD"},
    }
    created = _ok(world.member.post(REC, json=body), 201)
    assert created["origin"] == "manual"
    assert created["interval_count"] == 1
    schedule_id = created["id"]
    assert _ok(world.viewer.get(f"{REC}/{schedule_id}"))["name"] == "Rent"
    listed = _ok(world.viewer.get(REC, params={"origin": "manual"}))
    assert [i["id"] for i in listed["items"]] == [schedule_id]
    patched = _ok(
        world.member.patch(
            f"{REC}/{schedule_id}",
            json={"amount_min": {"amount": "-1300.00", "currency": "USD"}},
        )
    )
    assert patched["amount_min"]["amount"] == "-1300.00"
    bad_range = world.member.patch(
        f"{REC}/{schedule_id}", json={"amount_min": {"amount": "1.00", "currency": "USD"}}
    )
    assert problem_type(bad_range) == "invalid-amount-range"
    euro = world.member.post(
        REC, json={**body, "amount_min": {"amount": "-1.00", "currency": "EUR"}}
    )
    assert euro.status_code == 422
    assert problem_type(euro) == "currency-mismatch"
    assert world.viewer.patch(f"{REC}/{schedule_id}", json={"active": False}).status_code == 403
    assert world.viewer.delete(f"{REC}/{schedule_id}").status_code == 403
    hidden = world.member.post(REC, json={**body, "account_id": str(world.hidden.id)})
    assert hidden.status_code == 404
    unknown_payee = world.member.post(REC, json={**body, "payee_id": str(uuid.uuid4())})
    assert problem_type(unknown_payee) == "payee-not-found"
    assert household_audit(world.factories, world.household_id, "schedule.create")
    _ok(world.member.delete(f"{REC}/{schedule_id}"), 204)
    assert world.member.get(f"{REC}/{schedule_id}").status_code == 404


def test_schedule_on_hidden_account_is_not_found(world: World) -> None:
    row = world.ledger.run(make_scheduled_transaction, world.hidden)
    for client in (world.member, world.viewer):
        response = client.get(f"{REC}/{row.id}")
        assert response.status_code == 404
        assert problem_type(response) == "schedule-not-found"
    assert world.member.patch(f"{REC}/{row.id}", json={"active": False}).status_code == 404
    assert str(row.id) not in {i["id"] for i in _ok(world.member.get(REC))["items"]}
    assert str(row.id) in {i["id"] for i in _ok(world.owner.get(REC))["items"]}


def test_calendar(world: World) -> None:
    _ok(world.owner.post(f"{REC}/detect", json={}))
    body = _ok(world.member.get(CAL, params={"days": 30}))
    assert (body["date_from"], body["date_to"]) == ("2026-06-30", "2026-07-29")
    days = {d["on"]: d for d in body["days"]}
    assert set(days) == {"2026-07-03", "2026-07-05", "2026-07-17", "2026-07-20"}
    assert days["2026-07-03"]["events"][0]["kind"] == "income"
    power = days["2026-07-20"]["events"][0]
    assert power["amount"] == {"amount": "-90.00", "currency": "USD"}
    assert power["kind"] == "bill"
    assert D(body["income"]["amount"]) == D("5000.00")
    assert D(body["bills"]["amount"]) == D("105.99")
    assert D(body["net"]["amount"]) == D("4894.01")
    # The opening balance is the checking account's ledger balance today.
    opening = D(body["opening_balance"]["amount"])
    assert D(days["2026-07-20"]["balance"]["amount"]) == opening + D("5000.00") - D("105.99")
    # The owner also sees the hidden account's club on 2026-07-12.
    owner = _ok(world.owner.get(CAL, params={"days": 30}))
    assert "2026-07-12" in {d["on"] for d in owner["days"]}
    assert world.member.get(CAL, params={"days": 0}).status_code == 422
    assert world.member.get(CAL, params={"days": 367}).status_code == 422


def test_daily_job_detects_every_account(world: World) -> None:
    with world.factories.transaction() as db:
        set_context(db, world.household_id)
        ctx = JobContext(
            job_id=uuid.uuid4(),
            job_type=recurring_handler.DETECT_JOB_TYPE,
            attempt=1,
            max_attempts=1,
            household_id=world.household_id,
            session=db,
            deadline=datetime.max.replace(tzinfo=UTC),
        )
        recurring_handler.detect_household(
            ctx, recurring_handler.HouseholdDetectPayload(as_of=TODAY)
        )
    rows = _schedules(world)
    assert {r.account_id for r in rows} == {world.checking.id, world.hidden.id}
    assert len(rows) == 4


def test_two_plans_of_one_payee_stay_two_schedules(world: World) -> None:
    for i in range(6):
        day = add_months(date(2026, 1, 8), i)
        world.ledger.transaction(
            world.checking, amount="-9.99", posted_date=day, raw_payee="Cloud Store"
        )
        world.ledger.transaction(
            world.checking,
            amount="-29.99",
            posted_date=day + timedelta(days=2),
            raw_payee="Cloud Store",
        )
    first = _ok(world.member.post(f"{REC}/detect", json={}))
    assert first["created"] == 5
    cloud = sorted(r.amount_min for r in _schedules(world) if r.name == "Cloud Store")
    assert cloud == [D("-29.99"), D("-9.99")]
    again = _ok(world.member.post(f"{REC}/detect", json={}))
    assert (again["created"], again["updated"], again["unchanged"]) == (0, 0, 5)
